export const locales: Record<Locale, Messages> = { en, ru, es, fr, zh };

export function formatMessage(locale: Locale, key: keyof Messages | string, params: Record<string, unknown> = {}): string {
  const catalog = locales[locale] as Record<string, string>;
  const fallback = en as Record<string, string>;
  return (catalog[key] || fallback[key] || key).replace(/\{(\w+)\}/g, (_, name) => String(params[name] ?? '—'));
}
